deeper_reasoning_1:
\section*{Claim}
Multiplicative renormalisation of \(Z_A\) makes the complex zero definition of \(m_{\rm gap}\) invariant, and the fixed-shape fit then transfers this single invariant scale to \(T_c\), \(p_{\rm peak}\), and \(p_{\rm in}^{\pm}\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &Z_A(p;\mu)=R(\mu,\mu_0)Z_A(p;\mu_0),\qquad R(\mu,\mu_0)\ne0.\\
\text{(P2)}\quad &Z_A(-\omega_{\rm gap}^2;\mu)=0,\qquad m_{\rm gap}=\operatorname{Re}\omega_{\rm gap}.\\
\text{(P3)}\quad &Z_{A,{\rm fit}}(p)=\mathcal Z_A(x;\theta),\qquad x=p^2/m_{\rm gap}^2.\\
\text{(P4)}\quad &D(x;\theta):=\mathcal Z_A(x;\theta)^{-1}.\\
\text{(P5)}\quad &p_{\rm peak}=m_{\rm gap}\sqrt{x_{\rm peak}},\qquad \partial_xD(x_{\rm peak};\theta)=0.\\
\text{(P6)}\quad &p_{\rm in}^{\pm}=m_{\rm gap}\sqrt{x_\pm},\qquad \partial_x^2D(x_\pm;\theta)=0.\\
\text{(P7)}\quad &\mathcal D(\tau;\theta)=0,\qquad \tau:=T/m_{\rm gap}.
\end{aligned}
\]

\section*{Derivation}
By (P1),
\begin{align}
Z_A(-\omega^2;\mu)=0
&\Longleftrightarrow R(\mu,\mu_0)Z_A(-\omega^2;\mu_0)=0\\
&\Longleftrightarrow Z_A(-\omega^2;\mu_0)=0.
\end{align}
The selected non-zero zero is therefore unchanged by \(\mu\), hence
\begin{align}
\mu\frac{d}{d\mu}m_{\rm gap}=0.
\end{align}
Using \(x=p^2/m_{\rm gap}^2\), all derivative-defined momenta have the form
\begin{align}
p=m_{\rm gap}\sqrt{x_*},
\end{align}
where \(x_*\) is fixed by \(\theta\). Similarly, the deconfinement condition gives \(\tau=c_{\rm conf}(\theta)\), so
\begin{align}
T_c=c_{\rm conf}(\theta)m_{\rm gap}.
\end{align}

\section*{Final Result}
\[
\boxed{
\mu\frac{d m_{\rm gap}}{d\mu}=0,\qquad
\frac{T_c}{m_{\rm gap}},\frac{p_{\rm peak}}{m_{\rm gap}},\frac{p_{\rm in}^{\pm}}{m_{\rm gap}}
\text{ depend only on }\theta
}
\]
\hfill$\blacksquare$

deeper_reasoning_2:
\section*{Claim}
The Polyakov-loop sign-reversal argument is the minimal analytic mechanism by which the relevant effective potential can exchange a centre-broken minimum with a centre-symmetric minimum.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &V_{\rm pert}(\phi)=a\left[4\left(\widetilde\phi-\frac12\right)^2-1\right]^2,\qquad a>0.\\
\text{(P2)}\quad &0\le\widetilde\phi<1,\qquad y=\widetilde\phi-\frac12.\\
\text{(P3)}\quad &L(\phi)=\cos(\pi\phi).\\
\text{(P4)}\quad &\operatorname*{arg\,min}[-F]=\operatorname*{arg\,max}F.
\end{aligned}
\]

\section*{Derivation}
Let \(F(y)=(4y^2-1)^2\). Then
\begin{align}
\frac{dF}{dy}=16y(4y^2-1).
\end{align}
The relevant stationary or endpoint values are
\begin{align}
F(-1/2)&=0,&F(0)&=1,&\lim_{y\to(1/2)^-}F(y)&=0.
\end{align}
Since \(a>0\), \(V_{\rm pert}\) is minimised at \(\widetilde\phi=0\) and maximised at \(\widetilde\phi=1/2\):
\begin{align}
\operatorname*{arg\,min}V_{\rm pert}&=\{0\},\\
\operatorname*{arg\,max}V_{\rm pert}&=\{1/2\}.
\end{align}
By (P4),
\begin{align}
\operatorname*{arg\,min}[-V_{\rm pert}]=\{1/2\}.
\end{align}
Finally,
\begin{align}
L(0)&=1,&L(1/2)&=0.
\end{align}

\section*{Final Result}
\[
\boxed{
V_{\rm pert}:\ L=1,\qquad -V_{\rm pert}:\ L=0
}
\]
\hfill$\blacksquare$

deeper_reasoning_3:
\section*{Claim}
The infrared deformation family can be large at \(p=0\) in the propagator while remaining small in the inverse-dressing channels that enter the Polyakov-loop and quark-gap integrals.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &\delta G_A^{\sigma,\nu}(p)=\sigma a e^{-(p/\nu)^3},\qquad |\sigma|=1,\ a>0.\\
\text{(P2)}\quad &\delta Z_A^{-1}(p):=p^2\delta G_A^{\sigma,\nu}(p).\\
\text{(P3)}\quad &\delta I_0=\int_0^\infty\frac{dp}{2\pi^2}\delta Z_A^{-1}(p).\\
\text{(P4)}\quad &|f(p,k)|\le B_p\text{ in the deformed part of the scalar gap integral}.
\end{aligned}
\]

\section*{Derivation}
From (P1)--(P2),
\begin{align}
\delta G_A^{\sigma,\nu}(0)&=\sigma a,\\
\delta Z_A^{-1}(p)&=\sigma ap^2e^{-(p/\nu)^3},\\
\delta Z_A^{-1}(0)&=0.
\end{align}
Hence
\begin{align}
|\delta I_0|
&\le\frac{a}{2\pi^2}\int_0^\infty dp\,p^2e^{-(p/\nu)^3}.
\end{align}
With \(u=p/\nu\),
\begin{align}
|\delta I_0|
&\le\frac{a\nu^3}{2\pi^2}\int_0^\infty du\,u^2e^{-u^3}
=O(\nu^3).
\end{align}
For the direct scalar gap contribution,
\begin{align}
\left|\int_0^\infty dk^2\,\delta Z_A^{-1}(k)f(p,k)\right|
&\le aB_p\int_0^\infty dk^2\,k^2e^{-(k/\nu)^3}\\
&=2aB_p\nu^4\int_0^\infty du\,u^3e^{-u^3}\\
&=O(\nu^4).
\end{align}

\section*{Final Result}
\[
\boxed{
\delta G_A(0)\ne0,\qquad \delta Z_A^{-1}(0)=0,\qquad
\delta I_0=O(\nu^3),\qquad \delta M_q(p)_{\rm direct}=O(\nu^4)
}
\]
\hfill$\blacksquare$

deeper_reasoning_4:
\section*{Claim}
The Pagels-Stokar expression suppresses compact deep-infrared changes by the four-dimensional radial measure. If the scalar integrand changes only for \(0\le q\le\nu^2\), the induced change in \(f_\pi^2\) is bounded by a term proportional to \(\nu^4\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &f_\pi^2=\frac{N_c}{4\pi^2}\int_0^\infty dq\,qH(q).\\
\text{(P2)}\quad &\delta H(q)=0\quad\text{for }q>\nu^2.\\
\text{(P3)}\quad &|\delta H(q)|\le C_\nu\quad\text{for }0\le q\le\nu^2.\\
\text{(P4)}\quad &N_c>0.
\end{aligned}
\]

\section*{Derivation}
Varying (P1),
\begin{align}
\delta f_\pi^2
&=\frac{N_c}{4\pi^2}\int_0^\infty dq\,q\delta H(q)\\
&=\frac{N_c}{4\pi^2}\int_0^{\nu^2} dq\,q\delta H(q).
\end{align}
Therefore,
\begin{align}
|\delta f_\pi^2|
&\le \frac{N_c}{4\pi^2}\int_0^{\nu^2} dq\,q|\delta H(q)|\\
&\le \frac{N_cC_\nu}{4\pi^2}\int_0^{\nu^2}dq\,q\\
&=\frac{N_cC_\nu}{8\pi^2}\nu^4.
\end{align}

\section*{Final Result}
\[
\boxed{
|\delta f_\pi^2|\le\frac{N_cC_\nu}{8\pi^2}\nu^4
}
\]
\hfill$\blacksquare$

deeper_reasoning_5:
\section*{Claim}
A classical massive dressing has no finite positive-momentum peak, so the observed peak-plus-two-inflection structure of \(Z_A^{-1}\) is a nonclassical signature that justifies the three operational momentum regions.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &D_m(p)=\frac{p^2}{p^2+m^2},\qquad m>0.\\
\text{(P2)}\quad &D(p)=Z_A^{-1}(p).\\
\text{(P3)}\quad &p_{\rm in}^-<p_{\rm peak}<p_{\rm in}^+.\\
\text{(P4)}\quad &R_{\rm ir}=[0,p_{\rm in}^-),\quad R_{\rm sc}=[p_{\rm in}^-,p_{\rm in}^+],\quad R_{\rm uv}=(p_{\rm in}^+,\infty).
\end{aligned}
\]

\section*{Derivation}
Differentiate \(D_m\):
\begin{align}
\frac{dD_m}{dp}
&=\frac{(2p)(p^2+m^2)-p^2(2p)}{(p^2+m^2)^2}\\
&=\frac{2pm^2}{(p^2+m^2)^2}.
\end{align}
For \(p>0\), this derivative is positive. Hence \(D_m\) is strictly increasing and has no finite positive-momentum maximum.

The structure in (P3) therefore cannot be generated by a bare massive denominator alone. It creates a meaningful partition:
\begin{align}
R_{\rm ir}&=\text{region below the lower inflection point},\\
R_{\rm sc}&=\text{region containing the nonclassical peak},\\
R_{\rm uv}&=\text{region above the upper inflection point}.
\end{align}

\section*{Final Result}
\[
\boxed{
D_m'(p)>0\ (p>0)
\quad\Rightarrow\quad
p_{\rm in}^-<p_{\rm peak}<p_{\rm in}^+\text{ is a nonclassical dressing feature}
}
\]
\hfill$\blacksquare$

deeper_reasoning_6:
\section*{Claim}
The identification \(p_{\rm dec}\approx p_{\rm in}^-\) is justified as a sufficient boundary statement: below \(p_{\rm in}^-\), infrared kernels suppress deformations; at or above \(p_{\rm in}^-\), the deformation overlaps the strongly correlated region and can become observable.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &R_{\rm ir}=[0,p_{\rm in}^-),\qquad R_{\rm sc}=[p_{\rm in}^-,p_{\rm in}^+].\\
\text{(P2)}\quad &\delta O_\nu=\int_0^\infty dp\,K_O(p)p^2\delta G_A^{\sigma,\nu}(p).\\
\text{(P3)}\quad &|K_O(p)|\le B_{\rm ir}\text{ on }R_{\rm ir},\qquad B_{\rm ir}\text{ is small}.\\
\text{(P4)}\quad &K_O\text{ is not identically zero on }R_{\rm sc}.\\
\text{(P5)}\quad &p_{\rm dec}\text{ is the largest invisible deformation scale}.
\end{aligned}
\]

\section*{Derivation}
For \(\nu<p_{\rm in}^-\), the deformation is concentrated in \(R_{\rm ir}\), so
\begin{align}
|\delta O_\nu|
&\le aB_{\rm ir}\int_0^\infty dp\,p^2e^{-(p/\nu)^3}\\
&=aB_{\rm ir}\nu^3\int_0^\infty du\,u^2e^{-u^3}.
\end{align}
Thus the observable change is controlled by the small infrared kernel bound.

For \(\nu\ge p_{\rm in}^-\), the deformation overlaps \(R_{\rm sc}\). Since \(K_O\) is not identically zero there, the contribution from \(R_{\rm sc}\) is no longer bounded by \(B_{\rm ir}\). Therefore the deformation can become visible precisely when it reaches the lower inflection boundary.

\section*{Final Result}
\[
\boxed{
\nu<p_{\rm in}^-\Rightarrow \delta O_\nu\text{ is suppressed},\qquad
\nu\ge p_{\rm in}^-\Rightarrow \delta O_\nu\text{ can be visible},\qquad
p_{\rm dec}\approx p_{\rm in}^-
}
\]
\hfill$\blacksquare$

deeper_reasoning_7:
\section*{Claim}
The fitted inverse dressing is interpretable because its parameter groups have separable limiting fingerprints: \(z_{\rm sat}\) controls saturation, \((z_{\rm uv},c_{\rm uv},\gamma)\) controls ultraviolet logarithmic scaling, and \(z_{\rm peak}\) controls the leading ultraviolet-decoupling tail of the infrared component.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &Z_{A,{\rm fit}}(x)=Z_{A,{\rm ir}}(x)+Z_{A,{\rm uv}}(x),\qquad x=p^2/m_{\rm gap}^2.\\
\text{(P2)}\quad &Z_{A,{\rm ir}}(x)=\frac{z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}.\\
\text{(P3)}\quad &Z_{A,{\rm uv}}(x)=z_{\rm uv}[1+c_{\rm uv}\log(1+c_+x)]^\gamma.\\
\text{(P4)}\quad &c_+>0,\ c_->0,\ c_{\rm uv}>0,\ z_{\rm uv}>0.
\end{aligned}
\]

\section*{Derivation}
As \(x\to0^+\),
\begin{align}
xZ_{A,{\rm ir}}(x)
&=\frac{z_{\rm sat}-xz_{\rm peak}-xz_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}\to z_{\rm sat},\\
xZ_{A,{\rm uv}}(x)&\to0.
\end{align}
Hence
\begin{align}
G_{A,{\rm fit}}(0)=\frac{1}{z_{\rm sat}m_{\rm gap}^2}.
\end{align}
As \(x\to\infty\),
\begin{align}
\log(1+1/(c_-x))&=\frac{1}{c_-x}+O(x^{-2}),\\
Z_{A,{\rm ir}}(x)&=-\frac{z_{\rm peak}}{c_+^2x^2}+O(x^{-3}),\\
Z_{A,{\rm uv}}(x)&=z_{\rm uv}c_{\rm uv}^{\gamma}(\log x)^\gamma[1+o(1)].
\end{align}

\section*{Final Result}
\[
\boxed{
G_{A,{\rm fit}}(0)=\frac{1}{z_{\rm sat}m_{\rm gap}^2},\quad
Z_{A,{\rm ir}}(x)\sim-\frac{z_{\rm peak}}{c_+^2x^2},\quad
Z_{A,{\rm uv}}(x)\sim z_{\rm uv}c_{\rm uv}^{\gamma}(\log x)^\gamma
}
\]
\hfill$\blacksquare$

deeper_reasoning_8:
\section*{Claim}
The saturation mass \(m_{\rm sat}\) is not the same object as the zero-defined mass gap \(m_{\rm gap}\). Their relation contains the additional dimensionless saturation parameter \(z_{\rm sat}\), so changing \(G_A(0)\) is not equivalent to changing the physical mass-gap scale.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &G_A(0)=1/m_{\rm sat}^2.\\
\text{(P2)}\quad &G_{A,{\rm fit}}(0)=1/(z_{\rm sat}m_{\rm gap}^2).\\
\text{(P3)}\quad &z_{\rm sat}>0,\qquad m_{\rm gap}>0.\\
\text{(P4)}\quad &m_{\rm gap}=\operatorname{Re}\omega_{\rm gap},\qquad Z_A(-\omega_{\rm gap}^2)=0.\\
\text{(P5)}\quad &\delta G_A(0)\ne0,\qquad \delta Z_A^{-1}(0)=0\text{ for the infrared deformation}.
\end{aligned}
\]

\section*{Derivation}
Equating (P1) and (P2),
\begin{align}
\frac{1}{m_{\rm sat}^2}
&=\frac{1}{z_{\rm sat}m_{\rm gap}^2}.
\end{align}
Therefore,
\begin{align}
m_{\rm sat}^2=z_{\rm sat}m_{\rm gap}^2.
\end{align}
The mass \(m_{\rm sat}\) is controlled by both \(m_{\rm gap}\) and \(z_{\rm sat}\). Moreover, (P5) shows that the deformation can change \(G_A(0)\), and thus the saturation mass, while leaving the pointwise inverse-dressing deformation zero at \(p=0\). This separates the physical zero-defined scale from the zero-momentum propagator value.

\section*{Final Result}
\[
\boxed{
m_{\rm sat}^2=z_{\rm sat}m_{\rm gap}^2,\qquad
m_{\rm sat}\not\equiv m_{\rm gap}
}
\]
\hfill$\blacksquare$

deeper_reasoning_9:
\section*{Claim}
The physical-unit rewriting proves that the fit has one explicit kinematic mass scale. Changing from \(x=p^2/m_{\rm gap}^2\) to \(\bar x=p^2[{\rm GeV}^2]\) rescales only \(m_{\rm gap}\), \(c_\pm\), and \(z_{\rm sat}\) as required by dimensional consistency.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &x=\eta\bar x,\qquad \bar x=p^2[{\rm GeV}^2].\\
\text{(P2)}\quad &\eta=1/m_{\rm gap}[{\rm GeV}]^2.\\
\text{(P3)}\quad &Z_{A,{\rm ir}}(x)=\frac{z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}.\\
\text{(P4)}\quad &Z_{A,{\rm uv}}(x)=z_{\rm uv}[1+c_{\rm uv}\log(1+c_+x)]^\gamma.
\end{aligned}
\]

\section*{Derivation}
From (P2),
\begin{align}
m_{\rm gap}[{\rm GeV}]=\frac{1}{\sqrt{\eta}}.
\end{align}
Substituting \(x=\eta\bar x\) into the infrared term,
\begin{align}
Z_{A,{\rm ir}}(\eta\bar x)
&=\frac{(z_{\rm sat}/\eta)/\bar x-z_{\rm peak}-z_{\rm gh}\log(1+1/[(\eta c_-)\bar x])}{(1+(\eta c_+)\bar x)^2}.
\end{align}
Thus
\begin{align}
\bar z_{\rm sat}&=z_{\rm sat}/\eta,&
\bar c_-&=\eta c_-,&
\bar c_+&=\eta c_+.
\end{align}
The ultraviolet term becomes
\begin{align}
Z_{A,{\rm uv}}(\eta\bar x)
&=z_{\rm uv}[1+c_{\rm uv}\log(1+\bar c_+\bar x)]^\gamma,
\end{align}
so \(z_{\rm uv}\) and \(c_{\rm uv}\) are unchanged.

\section*{Final Result}
\[
\boxed{
m_{\rm gap}[{\rm GeV}]=\frac{1}{\sqrt{\eta}},\qquad
\bar c_\pm=\eta c_\pm,\qquad
\bar z_{\rm sat}=\frac{z_{\rm sat}}{\eta},\qquad
\bar z_i=z_i\ (i={\rm peak},{\rm gh},{\rm uv}),\quad \bar c_{\rm uv}=c_{\rm uv}
}
\]
\hfill$\blacksquare$

deeper_reasoning_10:
\section*{Claim}
The three goals form one dependency chain: the invariant complex zero defines the scale, fixed-shape observables use that scale, inflection points define the momentum regimes, infrared deformation bounds identify the decoupling boundary, and fit asymptotics assign physical roles to the parameters.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &\mu\,dm_{\rm gap}/d\mu=0.\\
\text{(P2)}\quad &T_c=c_{\rm conf}m_{\rm gap}.\\
\text{(P3)}\quad &p_{\rm in}^-<p_{\rm peak}<p_{\rm in}^+.\\
\text{(P4)}\quad &R_{\rm ir}=[0,p_{\rm in}^-),\quad R_{\rm sc}=[p_{\rm in}^-,p_{\rm in}^+],\quad R_{\rm uv}=(p_{\rm in}^+,\infty).\\
\text{(P5)}\quad &\nu<p_{\rm in}^-\Rightarrow \delta T_c\approx0,\quad \delta f_\pi\approx0.\\
\text{(P6)}\quad &Z_{A,{\rm fit}}(p)=Z_{A,{\rm ir}}(p^2/m_{\rm gap}^2)+Z_{A,{\rm uv}}(p^2/m_{\rm gap}^2).
\end{aligned}
\]

\section*{Derivation}
Premises (P1)--(P2) establish the physical scale claim:
\begin{align}
m_{\rm gap}\text{ is invariant and }T_c/m_{\rm gap}=c_{\rm conf}.
\end{align}
Premises (P3)--(P4) establish the three-region momentum claim:
\begin{align}
R_{\rm ir},R_{\rm sc},R_{\rm uv}
\text{ are determined by }p_{\rm in}^-,p_{\rm peak},p_{\rm in}^+.
\end{align}
Premise (P5) links the geometric boundary to the operational decoupling scale:
\begin{align}
p_{\rm dec}\approx p_{\rm in}^-.
\end{align}
Premise (P6), together with the limiting results for \(Z_{A,{\rm ir}}\) and \(Z_{A,{\rm uv}}\), establishes the interpretable-fit claim. Therefore the goals are not merely compatible; they reinforce one another.

\section*{Final Result}
\[
\boxed{
G1\wedge G2\wedge G3:
\quad
m_{\rm gap}\to (T_c,p_{\rm peak},p_{\rm in}^{\pm})\to p_{\rm dec}\approx p_{\rm in}^-\to Z_{A,{\rm fit}}\text{ interpretation}
}
\]
\hfill$\blacksquare$
